from pathlib import Path
p=Path('verificar.mjs')
s=p.read_text(encoding='utf-8')
old="""    const e=DB.addExtra({titulo:'Teste semanal auditável',tipo:'questoes',disciplina:'Teste',alvo:100,unidade:'questoes',periodo:'semanal',dataInicio:inicio,dataFim:hoje,contaMetricas:false}); DB.sincronizarDatasRecorrencia(e.id); DB.addExtraProgress(e.id,40,30,{data:inicio,acertos:30}); DB.addExtraProgress(e.id,90,25,{data:hoje,acertos:70}); ExtrasScreen.selDay=inicio; ExtrasScreen._calStart=inicio; ExtrasScreen.render(); const card=[...document.querySelectorAll('#extras-list .exd')].find(x=>x.dataset.id===e.id); const txt=card?card.textContent.replace(/\\s+/g,' '):''; const temMin=!!(card&&card.querySelector('.exd-min')); DB.deleteExtra(e.id); ExtrasScreen.selDay=hoje; ExtrasScreen.render(); return{txt,temMin};"""
new="""    const e=DB.addExtra({titulo:'Teste semanal auditável',tipo:'questoes',disciplina:'Teste',alvo:100,unidade:'questoes',periodo:'semanal',dataInicio:inicio,dataFim:hoje,contaMetricas:false}); DB.sincronizarDatasRecorrencia(e.id); DB.addExtraProgress(e.id,40,30,{data:inicio,acertos:30}); DB.addExtraProgress(e.id,90,25,{data:hoje,acertos:70}); ExtrasScreen.selDay=inicio; ExtrasScreen._calStart=inicio; ExtrasScreen.render(); let card=[...document.querySelectorAll('#extras-list .exd')].find(x=>x.dataset.id===e.id); const txt=card?card.textContent.replace(/\\s+/g,' '):''; const mais=card&&card.querySelector('.exd-reg-more'); if(mais) mais.click(); card=[...document.querySelectorAll('#extras-list .exd')].find(x=>x.dataset.id===e.id); const temMin=!!(card&&card.querySelector('.exd-min')); DB.deleteExtra(e.id); ExtrasScreen.selDay=hoje; ExtrasScreen._addMoreFor=null; ExtrasScreen.render(); return{txt,temMin};"""
if s.count(old)!=1: raise SystemExit(f'bloco esperado não encontrado de forma única: {s.count(old)}')
p.write_text(s.replace(old,new,1),encoding='utf-8')
print('Teste real ajustado para abrir Registrar mais antes de procurar minutos.')